CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$SELECT NULL::uuid$$;
CREATE FUNCTION fn_ca_horse_assigned_club(uuid) RETURNS uuid LANGUAGE sql AS $$SELECT md5('assigned')::uuid$$;
CREATE FUNCTION fn_ca_ledger_refusal_record(jsonb) RETURNS void LANGUAGE sql AS $$SELECT$$;
CREATE TABLE clubs(id uuid PRIMARY KEY,chip_treasury numeric,chip_pool numeric DEFAULT 0,updated_at timestamptz);
CREATE TABLE club_members(club_id uuid,user_id uuid,chip_balance numeric,membership_lifecycle_status text,updated_at timestamptz,PRIMARY KEY(club_id,user_id));
CREATE TABLE chip_ledger(id uuid DEFAULT gen_random_uuid(),performed_by uuid,from_type text,from_entity_id uuid,from_label text,to_type text,to_entity_id uuid,to_label text,amount numeric,category text,club_id uuid,union_id uuid,tournament_id uuid,description text,metadata jsonb DEFAULT '{}',pre_from_balance numeric,post_from_balance numeric,pre_to_balance numeric,post_to_balance numeric,CONSTRAINT chip_ledger_category_check CHECK(category IN('rakeback','club_bank_claim')),CONSTRAINT chip_ledger_from_type_check CHECK(from_type IN('player_wallet','club_treasury')));
CREATE TABLE chip_transactions(club_id uuid,from_user_id uuid,to_user_id uuid,amount numeric,transaction_type text,notes text,metadata jsonb,balance_after numeric);
CREATE TABLE ca_horse_club_split_receipts(operation_id uuid,kind text,horse_id uuid,club_id uuid);
CREATE TABLE ca_horse_club_split_late_returns(club_id uuid,horse_id uuid,amount numeric,op_id uuid,bank_before numeric,bank_after numeric);
CREATE TABLE financial_alerts(severity text,source text,message text,context jsonb);
CREATE TABLE ca_ledger_invariant_mode(mode text);
CREATE TABLE ca_ledger_invariant_store_mode(store text,mode text);
CREATE FUNCTION sr_assert(b boolean,msg text) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF b IS DISTINCT FROM true THEN RAISE EXCEPTION '%',msg;END IF;END$$;
INSERT INTO clubs VALUES(md5('club')::uuid,1000,0,now());
INSERT INTO club_members VALUES(md5('club')::uuid,md5('horse')::uuid,0,'departed',now());
INSERT INTO ca_horse_club_split_receipts VALUES('5b11c1b0-2026-1102-0000-000000000001','departed',md5('horse')::uuid,md5('club')::uuid);
CREATE SCHEMA extensions;
CREATE EXTENSION pgcrypto WITH SCHEMA extensions;
CREATE SEQUENCE chip_ledger_chain_seq;
ALTER TABLE chip_ledger ADD created_at timestamptz,ADD epoch_id uuid,ADD actor_service text,ADD db_role text,ADD correlation_id uuid,ADD settlement_id text,ADD idempotency_key text,ADD hand_id uuid,ADD table_id uuid,ADD chain_seq bigint,ADD prev_hash text,ADD row_hash text;
CREATE FUNCTION fn_ca_current_epoch() RETURNS uuid LANGUAGE sql AS $$SELECT md5('epoch')::uuid$$;
